content.oldText:
/* ─────────────────────────────────────────────────────────
 * MOTION STORYBOARD
 *
 * Tokens: --ease-out / --ease-in-out, --dur-press 120ms ·
 * --dur-fast 160ms · --dur-base 220ms · --dur-slow 320ms.
 * Solo transform/opacity se animan; color y fondo van con
 * transition de propiedades explícitas (nunca `all`).
 *
 * Botones y elementos pulsables
 *    0ms   :active → scale(0.97) con --dur-press --ease-out
 *   —      hover (solo pointer:fine) → fondo sutil, --dur-fast
 *   —      :focus-visible → anillo --focus-ring-width --color-focus, offset --focus-ring-offset
 *   —      busy → contenido blur(2px) + opacity .7, --dur-fast
 *
 * Navegación lateral
 *    0ms   al cambiar de pestaña, .nav-indicator hace
 *          translateY() hasta el item activo, --dur-base
 *          --ease-in-out; el item activo no pinta fondo propio
 *
 * Cambio de pestaña
 *    0ms   .tab-enter entra: opacity 0 → 1, translateY 6px → 0,
 *          --dur-base --ease-out (@starting-style)
 *
 * Listas (actividad, casos, documentos, resultados)
 *    0ms   cada fila: opacity 0 + translateY 8px → 0,
 *          --dur-base; stagger 30ms por fila, máximo 8 filas
 *
 * Chat
 *    0ms   burbuja nueva: opacity 0 + translateY 6px +
 *          scale .98 → reposo, --dur-base --ease-out
 *    —     "Checking…" (con BananaMark): fundido de opacidad
 *    —     tarjeta de propuesta inline: misma entrada que panel
 *
 * Avisos (.alert)
 *    0ms   entra desde arriba: translateY -8px + opacity,
 *          --dur-base --ease-out
 *    —     sale con opacity, --dur-fast; el notice se
 *          auto-cierra a los 6s en el hook
 *
 * Paneles (propuestas / operaciones pendientes)
 *    0ms   entrada: opacity + translateY 8px + scale .98,
 *          --dur-base --ease-out (@starting-style)
 *    0ms   pulso de atención: box-shadow --color-accent al
 *          35% → 0, keyframe único de 900ms
 *
 * Operador
 *    0ms   fila reconciliada: flash de fondo --color-success
 *          al 15% → transparente, 700ms, una vez
 *    —     .finding desaparece con opacity, --dur-fast
 *    —     "Draft a brief" ocupado → 3 líneas skeleton con
 *          shimmer desplazándose, 1.2s linear infinite
 *
 * Marca (BananaMark)
 *    —     loading: balanceo rotate(-10°) ↔ rotate(10°),
 *          origen 50% 70%, 1.4s --ease-in-out alternate;
 *          el rabito arrastra 0.1s
 *    —     hover logo: sacudida única 500ms (-6°→6°→0)
 *
 * prefers-reduced-motion: sin transform ni keyframes de
 * movimiento; quedan solo transiciones de opacity/color y el
 * pulso de opacidad del plátano.
 * ───────────────────────────────────────────────────────── */

.primary-button,
.secondary-button,
.text-button,
.nav-item,
.case-item,
.conversation-list button,
.document-list button,
.search-form .primary-button,
.composer button,
.suggestions button,
.history-heading button,
.alert button {
  transition:
    transform var(--dur-press) var(--ease-out),
    background-color var(--dur-fast) ease,
    color var(--dur-fast) ease,
    box-shadow var(--dur-fast) ease,
    opacity var(--dur-fast) ease;
}
.primary-button:active,
.secondary-button:active,
.text-button:active,
.nav-item:active,
.case-item:active,
.conversation-list button:active,
