content.oldText:
/* ─────────────────────────────────────────────────────────
 * MOTION STORYBOARD
 *
 * Tokens: --ease-out / --ease-in-out, --dur-press 120ms ·
 * --dur-fast 160ms · --dur-base 220ms · --dur-slow 320ms.
 * Solo transform/opacity se animan; color y fondo van con
 * transition de propiedades explícitas (nunca `all`).
 *
 * Botones y elementos pulsables
 *    0ms   :active → scale(0.97) con --dur-press --ease-out
 *   —      hover (solo pointer:fine) → fondo sutil, --dur-fast
 *   —      :focus-visible → anillo --focus-ring-width --color-focus, offset --focus-ring-offset
 *   —      busy → contenido blur(2px) + opacity .7, --dur-fast
 *
 * Navegación lateral
 *    0ms   al cambiar de pestaña, .nav-indicator hace
 *          translateY() hasta el item activo, --dur-base
 *          --ease-in-out; el item activo no pinta fondo propio
 *
 * Cambio de pestaña
 *    0ms   .tab-enter entra: opacity 0 → 1, translateY 6px → 0,
 *          --dur-base --ease-out (@starting-style)
 *
 * Listas (actividad, casos, documentos, resultados)
 *    0ms   cada fila: opacity 0 + translateY 8px → 0,
 *          --dur-base; stagger 30ms por fila, máximo 8 filas
 *
 * Chat
 *    0ms   burbuja nueva: opacity 0 + translateY 6px +
 *          scale .98 → reposo, --dur-base --ease-out
 *    —     "Checking…" (con BananaMark): fundido de opacidad
 *    —     tarjeta de propuesta inline: misma entrada que panel
 *
 * Avisos (.alert)
 *    0ms   entra desde arriba: translateY -8px + opacity,
 *          --dur-base --ease-out
 *    —     sale con opacity, --dur-fast; el notice se
 *          auto-cierra a los 6s en el hook
 *
 * Paneles (propuestas / operaciones pendientes)
 *    0ms   entrada: opacity + translateY 8px + scale .98,
 *          --dur-base --ease-out (@starting-style)
 *    0ms   pulso de atención: box-shadow --color-accent al
 *          35% → 0, keyframe único de 900ms
 *
 * Operador
 *    0ms   fila reconciliada: flash de fondo --color-success
 *          al 15% → transparente, 700ms, una vez
 *    —     .finding desaparece con opacity, --dur-fast
 *    —     "Draft a brief" ocupado → 3 líneas skeleton con
 *          shimmer desplazándose, 1.2s linear infinite
 *
 * Marca (BananaMark)
 *    —     loading: vuelta completa de 1.5s; acelera (0.65,0,0.35,1)
 *          hasta 372° en 0.87s, frena con overshoot y asienta en 360°
 *          a los 1.05s, reposo hasta la siguiente vuelta. Cuerpo y
 *          rabito son un solo <g>, origen en el centro del bbox
 *    —     hover logo: sacudida única 500ms (-6°→6°→0)
 *
 * prefers-reduced-motion: sin transform ni keyframes de
 * movimiento; quedan solo transiciones de opacity/color y el
 * pulso de opacidad del plátano.
 * ───────────────────────────────────────────────────────── */

.primary-button,
.secondary-button,
.text-button,
.nav-item,
.case-item,
.conversation-list button,
.document-list button,
.search-form .primary-button,
.composer button,
.suggestions button,
.history-heading button,
.alert button {
  transition:
    transform var(--dur-press) var(--ease-out),
    background-color var(--dur-fast) ease,
    color var(--dur-fast) ease,
    box-shadow var(--dur-fast) ease,
    opacity var(--dur-fast) ease;
}
.primary-button:active,
.secondary-button:active,
.text-button:active,
.nav-item:active,
.case-item:active,
.conversation-list button:active,
.document-list button:active,
.composer button:active,
.suggestions button:active {
  transform: scale(0.97);
}
@media (hover: hover) and (pointer: fine) {
  .case-item:hover,
  .document-list button:hover,
  .conversation-list button:hover,
  .suggestions button:hover {
    background: var(--color-nav-hover);
  }
  .text-button:hover svg {
    transform: translateX(2px);
  }
}
.text-button svg {
  transition: transform var(--dur-fast) var(--ease-out);
}
button[disabled] {
  cursor: default;
}
.button-content {
  transition:
    filter var(--dur-fast) ease,
    opacity var(--dur-fast) ease;
}
button[disabled] > .button-content {
  filter: blur(2px);
  opacity: 0.7;
}

nav {
  position: relative;
}
.nav-indicator {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 46px;
  background: var(--color-accent-soft);
  border-radius: var(--radius-md);
  transition: transform var(--dur-base) var(--ease-in-out);
  pointer-events: none;
}
.nav-item {
  position: relative;
}
nav .nav-item.active {
  background: transparent;
}

.tab-enter {
  transition:
    opacity var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
}
@starting-style {
  .tab-enter {
    opacity: 0;
    transform: translateY(6px);
  }
}

@keyframes stagger-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.stagger-in {
  animation: stagger-in var(--dur-base) var(--ease-out) both;
  animation-delay: calc(var(--i, 0) * 30ms);
}

.message {
  transition:
    opacity var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
}
@starting-style {
  .message {
    opacity: 0;
    transform: translateY(6px) scale(0.98);
  }
}
.thinking {
  transition: opacity var(--dur-fast) ease;
}
@starting-style {
  .thinking {
    opacity: 0;
  }
}

.alert {
  transition:
    opacity var(--dur-fast) ease,
    transform var(--dur-base) var(--ease-out);
}
@starting-style {
  .alert {
    opacity: 0;
    transform: translateY(-8px);
  }
}
.alert.leaving {
  opacity: 0;
  transition-duration: var(--dur-fast);
}

.panel.approvals {
  transition:
    opacity var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
  animation: proposal-pulse 900ms var(--ease-out) 1;
}
@starting-style {
  .panel.approvals {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
}
@keyframes proposal-pulse {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--color-accent) 35%, transparent);
  }
  100% {
    box-shadow: 0 0 0 18px transparent;
  }
}
.confirmation-code {
  font-family: ui-monospace, Menlo, monospace;
  background: var(--color-accent-soft);
  border-radius: var(--radius-sm);
  padding: 2px 8px;
