@keyframes stagger-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.stagger-in {
  animation: stagger-in var(--dur-base) var(--ease-out) both;
  animation-delay: calc(var(--i, 0) * 30ms);
}

.message {
  transition:
    opacity var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
}
@starting-style {
  .message {
    opacity: 0;
    transform: translateY(6px) scale(0.98);
  }
}
.thinking {
  transition: opacity var(--dur-fast) ease;
}
@starting-style {
  .thinking {
    opacity: 0;
  }
}

.alert {
  transition:
    opacity var(--dur-fast) ease,
    transform var(--dur-base) var(--ease-out);
}
@starting-style {
  .alert {
    opacity: 0;
    transform: translateY(-8px);
  }
}
.alert.leaving {
  opacity: 0;
  transition-duration: var(--dur-fast);
}

.panel.approvals {
  transition:
    opacity var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
  animation: proposal-pulse 900ms var(--ease-out) 1;
}
@starting-style {
  .panel.approvals {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
}
@keyframes proposal-pulse {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--color-accent) 35%, transparent);
  }
  100% {
    box-shadow: 0 0 0 18px transparent;
  }
}
.confirmation-code {
  font-family: ui-monospace, Menlo, monospace;
  background: var(--color-accent-soft);
  border-radius: var(--radius-sm);
  padding: 2px 8px;
  letter-spacing: 0.08em;
  font-weight: 700;
  color: var(--forest);
}

.chat-proposals {
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: var(--paper);
}
.proposal-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition:
    opacity var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
  animation: proposal-pulse 900ms var(--ease-out) 1;
}
@starting-style {
  .proposal-card {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
}
.proposal-card .proposal-amount {
  font-size: 22px;
  color: var(--forest);
}
.proposal-card small {
  color: var(--muted);
}
.proposal-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}
.proposal-card.leaving,
.panel.approvals .leaving {
  opacity: 0;
  transform: scale(0.98);
  transition:
    opacity var(--dur-fast) ease,
    transform var(--dur-fast) ease;
}
.panel.approvals > div {
  transition:
    opacity var(--dur-fast) ease,
    transform var(--dur-fast) ease;
}
.proposal-card.pending {
  border-style: dashed;
  box-shadow: none;
  animation: none;
}

.reconciliation-row {
  border-radius: var(--radius-md);
  transition: background-color var(--dur-fast) ease;
}
.reconciliation-row.reconciled-flash {
  animation: reconcile-flash 700ms var(--ease-out) 1;
}
@keyframes reconcile-flash {
  0% {
    background: color-mix(in srgb, var(--color-success) 15%, transparent);
  }
  100% {
    background: transparent;
  }
}
.finding {
  transition: opacity var(--dur-fast) ease;
}
.finding.fading {
  opacity: 0;
}
.brief-skeleton {
  margin: 12px 0 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.brief-skeleton i {
  display: block;
  height: 13px;
  border-radius: var(--radius-sm);
  background: linear-gradient(
    90deg,
    var(--color-nav-hover) 25%,
    var(--color-accent-soft) 50%,
    var(--color-nav-hover) 75%
  );
  background-size: 300% 100%;
  animation: skeleton-shimmer 1.2s linear infinite;
}
.brief-skeleton i:nth-child(2) {
  width: 82%;
}
.brief-skeleton i:nth-child(3) {
  width: 64%;
}
@keyframes skeleton-shimmer {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: -100% 0;
  }
}

.banana-mark-icon {
  display: inline-flex;
}
.banana-loading .banana-shape {
  transform-box: view-box;
  transform-origin: 16.9px 15.4px;
  animation: banana-spin 1.5s linear infinite;
}
@keyframes banana-spin {
  0% {
    transform: rotate(0deg);
    animation-timing-function: cubic-bezier(0.65, 0, 0.35, 1);
  }
  58% {
    transform: rotate(372deg);
    animation-timing-function: cubic-bezier(0.2, 0, 0, 1);
  }
  70% {
    transform: rotate(360deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
.banana-wiggle {
  animation: banana-wiggle 0.5s var(--ease-in-out) 1;
}
@keyframes banana-wiggle {
  0% {
    transform: rotate(0deg);
  }
  33% {
    transform: rotate(-6deg);
  }
  66% {
    transform: rotate(6deg);
  }
  100% {
    transform: rotate(0deg);
  }
}
.brand-symbol {
  display: inline-flex;
}
.loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}
.loading .banana-mark-icon {
  color: var(--color-spinner);
}

@media (prefers-reduced-motion: reduce) {
  .nav-indicator,
  .tab-enter,
  .message,
  .thinking,
  .alert,
  .panel.approvals,
  .proposal-card,
  .primary-button,
  .secondary-button,
  .text-button,
  .nav-item,
  .case-item,
  .conversation-list button,
  .document-list button,
  .composer button,
  .suggestions button {
    transition:
      opacity var(--dur-fast) ease,
      background-color var(--dur-fast) ease,
      color var(--dur-fast) ease;
  }
  .tab-enter,
  .message,
  .alert,
  .panel.approvals,
  .proposal-card {
    transform: none;
  }
  @starting-style {
    .tab-enter,
    .message,
    .alert,
    .panel.approvals,
    .proposal-card,
    .thinking {
      opacity: 0;
      transform: none;
    }
  }
  .stagger-in,
  .panel.approvals,
  .proposal-card,
  .reconciliation-row.reconciled-flash,
  .brief-skeleton i,
  .banana-loading .banana-shape,
  .banana-wiggle {
    animation: none;
  }
  .banana-loading .banana-shape {
    animation: banana-breathe 1.4s ease-in-out infinite alternate;
  }
  @keyframes banana-breathe {
    from {
      opacity: 0.6;
    }
    to {
      opacity: 1;
    }
  }
}

