import('playwright').then(async ({ chromium }) => {
  const b = await chromium.launch();
  const p = await b.newPage();
  await p.setContent(\`<svg width=352 height=352 viewBox='0 0 32 32'><g class='banana-shape'>
    <path id='body' d='M25 4c1 13-7 22-20 20 6 9 25 1 23-16Z' fill='currentColor'/>
    <path id='stem' d='M25.4 4.6c1.6-0.5 2.8-1.4 3.4-3.1' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round'/>
  </g></svg>\`);
  const r = await p.evaluate(() => {
    const body = document.getElementById('body');
    const stem = document.getElementById('stem');
    const svg = stem.ownerSVGElement;
    const pt = (x, y) => { const p = svg.createSVGPoint(); p.x = x; p.y = y; return p; };
    const covered = (x, y) => body.isPointInFill(pt(x, y)) || stem.isPointInStroke(pt(x, y));
    const gaps = [];
    // scan a fine grid over the junction region (x 24-27, y 3-7); report
    // uncovered cells that are INSIDE the silhouette's expected area:
    // check each row y: leftmost and rightmost covered x — any hole between them = notch
    for (let y = 3.0; y <= 7.0; y += 0.1) {
      let xs = [];
      for (let x = 23.5; x <= 29.5; x += 0.1) if (covered(x, y)) xs.push(x);
      if (xs.length) {
        // holes inside the covered span
        for (let x = xs[0] + 0.1; x < xs[xs.length - 1]; x += 0.1)
          if (!covered(x, y)) gaps.push([+x.toFixed(1), +y.toFixed(1)]);
      }
    }
    return { tipCovered: covered(25, 4), gaps: gaps.slice(0, 20), gapCount: gaps.length };
  });
  console.log(JSON.stringify(r));
  await b.close();
});
"

